pm.test('Appointment matches the submitted data', () => {
  const data = pm.response.json()
  const sent = JSON.parse(pm.request.body.raw)

  pm.expect(data.id).to.be.a('number')
  pm.expect(data.doctor).to.equal(sent.doctor)
  pm.expect(data.patient).to.equal(sent.patient)
  pm.expect(data.date).to.equal(sent.date)
})

